package com.internship.eligibility.service;
import com.internship.eligibility.dto.AuthDtos.*; import com.internship.eligibility.entity.*; import com.internship.eligibility.exception.ApiException; import com.internship.eligibility.repository.*; import com.internship.eligibility.security.JwtService; import org.springframework.http.HttpStatus; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service;
@Service public class AuthService {private final UserRepository users; private final StudentRepository students; private final PasswordEncoder encoder; private final JwtService jwt;
 public AuthService(UserRepository u,StudentRepository s,PasswordEncoder e,JwtService j){users=u;students=s;encoder=e;jwt=j;}
 public UserResponse register(RegisterRequest r){if(users.findByEmailIgnoreCase(r.email()).isPresent())throw new ApiException("Email already registered",HttpStatus.CONFLICT); User u=new User();u.setName(r.name());u.setEmail(r.email().toLowerCase());u.setPassword(encoder.encode(r.password()));u.setRole(Role.STUDENT);users.save(u);Student s=new Student();s.setUser(u);s.setPhone(r.phone());s.setBranch(r.branch());s.setYear(r.year());s.setCgpa(r.cgpa());students.save(s);return new UserResponse(u.getId(),u.getName(),u.getEmail(),u.getRole().name());}
 public LoginResponse login(LoginRequest r){User u=users.findByEmailIgnoreCase(r.email()).orElseThrow(()->new ApiException("Invalid email or password",HttpStatus.UNAUTHORIZED));if(!encoder.matches(r.password(),u.getPassword())||!u.getRole().name().equals(r.role().replace("ROLE_","")))throw new ApiException("Invalid email, password or role",HttpStatus.UNAUTHORIZED);return new LoginResponse(jwt.generate(u.getEmail(),u.getRole().name()),new UserResponse(u.getId(),u.getName(),u.getEmail(),u.getRole().name()));}}
